<script setup>
import { ref, computed, reactive, watch, onMounted, readonly } from 'vue';
import { useWidgets } from '@store/widgets';
import { Group, NewBadge, InputLabel, InputGroup, Text, Button, Toggle, Tooltip, Textarea, ColorPicker, ProBadge, MultiSelect, Select } from '@components';
import API from '@util/API'
import { useTranslation } from '../../composables/useTranslation';

const { t } = useTranslation();

const $widget = useWidgets();
const isLocked = computed(() => !formychat_admin_vars.is_premium)

const icon = computed(() => $widget.currentWidget.config?.icon || {});
const form = computed(() => $widget.currentWidget.config?.form || {});
const target = computed(() => $widget.currentWidget.config?.target || {})
const integrations = computed(() => {
    // Ensure integrations object exists on the store
    if (!$widget.currentWidget.config.integrations) {
        $widget.currentWidget.config.integrations = {}
    }
    return $widget.currentWidget.config.integrations
})

const fluentCRM = computed(() => {
    // Ensure fluent-crm object and its fields_mapping exist on the store
    if (!integrations.value['fluent-crm']) {
        integrations.value['fluent-crm'] = { fields_mapping: [ { from: 'email', to: 'email' } ] }
    } else if (!Array.isArray(integrations.value['fluent-crm'].fields_mapping)) {
        integrations.value['fluent-crm'].fields_mapping = [ { from: 'email', to: 'email' } ]
    }
    return integrations.value['fluent-crm']
})

const mailchimp = computed(() => {
    // Ensure mailchimp object and its fields_mapping exist on the store
    if (!integrations.value['mailchimp']) {
        integrations.value['mailchimp'] = {
            enabled: false,
            fields_mapping: [],
            lists: [],
            tags: [],
            skip_if_exists: false
        }
    } else if (!Array.isArray(integrations.value['mailchimp'].fields_mapping)) {
        integrations.value['mailchimp'].fields_mapping = []
    }
    return integrations.value['mailchimp']
})

const pages = computed(() => $widget.contents.pages ? $widget.contents.pages.map(p => ({ ...p, label: (p.label || t('untitled_page')) })) : [])

// Ensure pro-only flags remain disabled when not premium
watch(isLocked, (locked) => {
    if (locked) {
        form.value.google_analytics = false
        form.value.fluent_crm = false
    }
}, { immediate: true })

import { DotLottieVue } from '@lottiefiles/dotlottie-vue'
const animationPath = formychat_admin_vars.public + '/js/animation.json';

const routeToEdit = () => {
    $widget.states.showSuccess = false
    $widget.currentWidget.isNew = false
    $widget.editWidget($widget.currentWidget)
}

const state = reactive({
    is_loading_fluentcrm: false,
    is_fetching_fluentcrm_meta: false,
    is_fetching_mailchimp_meta: false,
})
const additional = ref(formychat_admin_vars.additional || {})

const installFluentCRM = async () => {
    state.is_loading_fluentcrm = true
    // Make a request to integration install.
    const response = await API.post(`integrations/install`, {
        integration_id: 'fluent-crm',
        action: 'install'
    })

    state.is_loading_fluentcrm = false

    if (response.data.success) {
        additional.value.fluentcrm.is_installed = true
        additional.value.fluentcrm.is_active = true
        additional.value.fluentcrm.is_enabled = true

        refresh_fluentcrm_meta()
    }
}

const mailchimp_notice = computed(() => {
    // Check if integration is turned off first
    if (!additional.value.mailchimp || !additional.value.mailchimp.is_enabled) {
        return {
            title: t('mailchimp_module_not_active'),
            desc: t('activate_mailchimp_first'),
            button: {
                label: t('activate_mailchimp_arrow'),
                onClick: async () => {
                    state.is_fetching_mailchimp_meta = true
                    const response = await API.post(`integrations`, {
                        integration_id: 'mailchimp',
                        enabled: true
                    })
                    state.is_fetching_mailchimp_meta = false
                    if (response.data && response.data.success) {
                        additional.value.mailchimp.is_enabled = true
                        refresh_mailchimp_meta()
                    }
                }
            }
        }
    }
    // Check if API key is not connected (no audiences loaded)
    if (!mailchimp_lists.value.length) {
        return {
            title: t('mailchimp_api_not_connected'),
            desc: t('connect_mailchimp_in_integrations'),
            button: {
                label: t('go_to_mailchimp_module'),
                link: '/wp-admin/admin.php?page=formychat-integrations#/'
            }
        }
    }
    return null
})

const fluentcrm_notice = computed(() => {
    if (!additional.value.fluentcrm.is_installed) {
        return {
            title: t('fluentcrm_not_installed'),
            desc: t('install_fluentcrm_first'),
            button: {
                label: t('install_fluentcrm_arrow'),
                onClick: installFluentCRM
            }
        }
    }
    if (!additional.value.fluentcrm.is_active) {
        return {
            title: t('fluentcrm_not_active'),
            desc: t('activate_fluentcrm_plugin'),
            button: {
                label: t('activate_fluentcrm_arrow'),
                onClick: installFluentCRM
            }
        }
    }
    if (!additional.value.fluentcrm.is_enabled) {
        return {
            title: t('fluentcrm_not_enabled'),
            desc: t('enable_fluentcrm_integration'),
            button: {
                label: t('enable_fluentcrm_arrow'),
                onClick: async () => {
                    state.is_loading_fluentcrm = true
                    // Make a request to integrations to update integration to enabled.
                    const response = await API.post(`integrations`, {
                        integration_id: 'fluent-crm',
                        enabled: true
                    })

                    state.is_loading_fluentcrm = false

                    if (response.data && response.data.success) {
                        additional.value.fluentcrm.is_enabled = true

                        refresh_fluentcrm_meta()
                    }
                }
            }
        }
    }

    return null
})

const form_field_options = computed(() => {
    let result = []
    for (const [name, field] of Object.entries($widget.fields)) {
        result.push({ label: field, value: name })
    }
    return result
})

// Get Mailchimp fields for each mapping row, excluding already mapped fields
const getMailchimpFieldOptions = (currentMap) => {
    // Get all currently mapped field values (except the current one)
    const mappedFields = mailchimp.value.fields_mapping
        .filter(m => m !== currentMap)
        .map(m => m.to)
        .filter(to => to) // Remove empty values

    // Filter fields based on whether this is the EMAIL mapping or not
    return mailchimp_fields.value.filter(field => {
        const fieldValue = field.value || field.key

        // If this is the readonly EMAIL mapping, only show EMAIL
        if (currentMap.readonly && currentMap.to === 'EMAIL') {
            return fieldValue === 'EMAIL'
        }

        // For other mappings:
        // 1. Exclude EMAIL field
        // 2. Exclude already mapped fields
        return fieldValue !== 'EMAIL' && !mappedFields.includes(fieldValue)
    })
}

// Check if Mailchimp ADDRESS fields are incomplete
const mailchimp_address_incomplete = computed(() => {
    const mappedFields = (mailchimp.value.fields_mapping || [])
        .map(m => m.to)
        .filter(to => to && to.startsWith('ADDRESS.'))

    if (mappedFields.length === 0) {
        return false
    }

    // Required ADDRESS fields
    const requiredFields = ['ADDRESS.addr1', 'ADDRESS.city', 'ADDRESS.state', 'ADDRESS.zip']
    const hasAllRequired = requiredFields.every(field => mappedFields.includes(field))

    return !hasAllRequired
})

// Get FluentCRM fields for each mapping row, excluding already mapped fields
const getFluentCRMFieldOptions = (currentMap) => {
    // Get all currently mapped field values (except the current one)
    const mappedFields = fluentCRM.value.fields_mapping
        .filter(m => m !== currentMap)
        .map(m => m.to)
        .filter(to => to) // Remove empty values

    // Filter fields based on whether this is the email mapping or not
    return fluentcrm_fields.value.filter(field => {
        const fieldValue = field.value || field.key

        // If this is the readonly email mapping, only show email
        if (currentMap.readonly && currentMap.to === 'email') {
            return fieldValue === 'email'
        }

        // For other mappings:
        // 1. Exclude email field
        // 2. Exclude already mapped fields
        return fieldValue !== 'email' && !mappedFields.includes(fieldValue)
    })
}

// Placeholder Lists/Tags; will be populated via REST later
const fluentcrm_lists = ref([])
const fluentcrm_tags = ref([])
const fluentcrm_fields = ref([])

// Mailchimp Audiences/Tags/Fields
const mailchimp_lists = ref([])
const mailchimp_tags = ref([])
const mailchimp_fields = ref([])

const add_field_map = () => {
    // Safety: ensure mapping array exists before push
    if (!Array.isArray(fluentCRM.value.fields_mapping)) {
        fluentCRM.value.fields_mapping = []
    }
    fluentCRM.value.fields_mapping.push({ from: '', to: '' })
}
const remove_field_map = (index) => {
    fluentCRM.value.fields_mapping.splice(index, 1)
}

const add_mailchimp_field_map = () => {
    if (!Array.isArray(mailchimp.value.fields_mapping)) {
        mailchimp.value.fields_mapping = []
    }
    mailchimp.value.fields_mapping.push({ from: '', to: '' })
}
const remove_mailchimp_field_map = (index) => {
    mailchimp.value.fields_mapping.splice(index, 1)
}

const refresh_fluentcrm_meta = async () => {

    // If not installed or activated.
    if (!additional.value.fluentcrm.is_installed
        || !additional.value.fluentcrm.is_active
        || !additional.value.fluentcrm.is_enabled) {
        return
    }

    try {

        state.is_fetching_fluentcrm_meta = true

        const response = await API.get(`integrations/fluentcrm_meta`)

        state.is_fetching_fluentcrm_meta = false

        if (response.data && response.data.success && response.data) {
            const data = response.data

            // Update lists
            fluentcrm_lists.value = data.lists || []

            // Update tags  
            fluentcrm_tags.value = data.tags || []

            // Update CRM field options
            fluentcrm_fields.value = data.fields || []

            initFluentCRMFieldsMapping()
        }
    } catch (error) {
        console.error('Error fetching FluentCRM meta:', error)
    }

}

const normalize_key = (key) => String(key || '').toLowerCase().trim()
const guess_email_field = () => {
    const keys = Object.keys($widget.fields || {})
    if (!keys.length) return ''

    const normalized = keys.map(k => ({ original: k, norm: normalize_key(k) }))

    // Exact match
    const exact = normalized.find(k => k.norm === 'email')
    if (exact) return exact.original

    // Starts/ends with email
    const edge = normalized.find(k => k.norm.startsWith('email') || k.norm.endsWith('email'))
    if (edge) return edge.original

    // Contains email
    const contains = normalized.find(k => k.norm.indexOf('email') !== -1)
    if (contains) return contains.original

    // Heuristic for 'mail' but avoid provider substrings
    const mail = normalized.find(k => k.norm.includes('mail') && !k.norm.includes('gmail') && !k.norm.includes('hotmail') && !k.norm.includes('yahoo'))
    if (mail) return mail.original

    return ''
}

const initFluentCRMFieldsMapping = () => {

    // Ensure array
    fluentCRM.value.fields_mapping = Array.isArray(fluentCRM.value.fields_mapping) ? fluentCRM.value.fields_mapping : []

    // If empty, seed with intelligent default
    if (fluentCRM.value.fields_mapping.length === 0) {
        fluentCRM.value.fields_mapping.push({
            from: guess_email_field(),
            to: 'email',
            readonly: true
        })
    }

}

const refresh_mailchimp_meta = async (force_refresh = false) => {
    try {
        state.is_fetching_mailchimp_meta = true

        const url = force_refresh
            ? 'integrations/mailchimp_meta?force_refresh=1'
            : 'integrations/mailchimp_meta'
        const response = await API.get(url)

        state.is_fetching_mailchimp_meta = false

        if (response.data && response.data.success) {
            const data = response.data

            // Update lists
            mailchimp_lists.value = data.lists || []

            // Update tags
            mailchimp_tags.value = data.tags || []

            // Update Mailchimp field options
            mailchimp_fields.value = data.fields || []

            // Ensure EMAIL field is always available in the dropdown
            const hasEmail = mailchimp_fields.value.some(field => field.key === 'EMAIL' || field.value === 'EMAIL')
            if (!hasEmail) {
                mailchimp_fields.value.unshift({
                    key: 'EMAIL',
                    label: t('email'),
                    value: 'EMAIL',
                    type: 'email',
                    required: true
                })
            }

            initMailchimpFieldsMapping()
        }
    } catch (error) {
        console.error('Error fetching Mailchimp meta:', error)
        state.is_fetching_mailchimp_meta = false
    }
}

const initMailchimpFieldsMapping = () => {
    // Ensure array
    mailchimp.value.fields_mapping = Array.isArray(mailchimp.value.fields_mapping) ? mailchimp.value.fields_mapping : []

    // Find if EMAIL mapping already exists
    let hasEmailMapping = false
    for (const map of mailchimp.value.fields_mapping) {
        if (map.to === 'EMAIL') {
            map.readonly = true
            hasEmailMapping = true
            break
        }
    }

    // If no EMAIL mapping exists, add it at the beginning
    if (!hasEmailMapping) {
        mailchimp.value.fields_mapping.unshift({
            from: guess_email_field(),
            to: 'EMAIL',
            readonly: true
        })
    }
}

const handleMailchimpButtonClick = () => {
    if (mailchimp_notice.value.button.onClick) {
        mailchimp_notice.value.button.onClick()
    } else if (mailchimp_notice.value.button.link) {
        window.location.href = mailchimp_notice.value.button.link
    }
}

onMounted(() => {
    $widget.fetchFields()
    refresh_fluentcrm_meta()

    // Try to load Mailchimp data if enabled
    if (additional.value.mailchimp && additional.value.mailchimp.is_enabled) {
        refresh_mailchimp_meta()
    }
})

</script>
