            <InputGroup>
                <div class="flex flex-wrap items-center justify-between gap-2">
                    <Toggle :locked="isLocked" v-model="form.google_analytics"
                        :hints="t('google_analytics_hint')"> {{ t('google_analytics') }}
                    </Toggle>
                    <a href="https://wppool.dev/docs/how-to-set-up-google-analytics-on-formychat-view-form-conversions/" target="_blank" class="flex items-center gap-1 bg-gray-100 border border-gray-200 hover:bg-gray-50 transition text-gray-700 px-3 py-1.5 rounded-full text-xs font-medium">
